const DEVELOPMENT_GATE = false;
if (!DEVELOPMENT_GATE) throw new Error('DEVELOPMENT_GATE_CLOSED: approve the Google Ads ingest before changing this value');
return $input.all();

const payload = $json.body ?? $json;
const fail = code => { throw new Error('GOOGLE_ADS_PAYLOAD_INVALID:' + code); };
const isoDay = value => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value || '')) return false;
  const parsed = Date.parse(value + 'T00:00:00Z');
  return Number.isFinite(parsed) && new Date(parsed).toISOString().slice(0, 10) === value;
};
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) fail('OBJECT_REQUIRED');
if (payload.schemaVersion !== 1 || payload.source !== 'google_ads') fail('SCHEMA');
if (payload.customerId !== '9329387049') fail('CUSTOMER');
if (payload.currencyCode !== 'GBP' || payload.timeZone !== 'Europe/London') fail('ACCOUNT_SETTINGS');
if (!['incremental','correction','backfill'].includes(payload.mode)) fail('MODE');
if (!payload.window || !isoDay(payload.window.start) || !isoDay(payload.window.end)) fail('WINDOW');
const start = Date.parse(payload.window.start + 'T00:00:00Z');
const end = Date.parse(payload.window.end + 'T00:00:00Z');
if (start > end || payload.window.start < '2025-01-01' || (end - start) / 86400000 > 34) fail('WINDOW_BOUNDS');
if (!/^\d{4}-\d{2}-\d{2}T/.test(payload.generatedAt || '') || !Number.isFinite(Date.parse(payload.generatedAt)) || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(payload.requestId || '')) fail('REQUEST_METADATA');
if (!Array.isArray(payload.campaignDaily) || !Array.isArray(payload.campaignCountryDaily)) fail('ROWS');
if (payload.campaignDaily.length > 200000 || payload.campaignCountryDaily.length > 500000) fail('ROW_LIMIT');
const finite = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;
const micros = value => typeof value === 'string' && /^[0-9]+$/.test(value);
const campaignIds = new Set();
for (const row of payload.campaignDaily) {
  if (!row || !isoDay(row.day) || row.day < payload.window.start || row.day > payload.window.end || !/^[0-9]+$/.test(row.campaignId || '') || typeof row.campaignName !== 'string' || row.campaignName.length > 1024 || !row.campaignStatus || !row.channelType || !row.channelSubtype || !micros(row.costMicros) || !finite(row.impressions) || !finite(row.clicks) || !finite(row.conversions) || !finite(row.conversionValue)) fail('CAMPAIGN_ROW');
  campaignIds.add(row.day + ':' + row.campaignId);
}
for (const row of payload.campaignCountryDaily) {
  if (!row || !isoDay(row.day) || row.day < payload.window.start || row.day > payload.window.end || !/^[0-9]+$/.test(row.campaignId || '') || !campaignIds.has(row.day + ':' + row.campaignId) || !/^[0-9]+$/.test(row.countryCriterionId || '') || (row.countryCode && !/^[A-Z]{2}$/.test(row.countryCode)) || !['us','gb','eur','aus','other'].includes(row.regionCode) || typeof row.targetingLocation !== 'boolean' || !micros(row.costMicros) || !finite(row.impressions) || !finite(row.clicks) || !finite(row.conversions) || !finite(row.conversionValue)) fail('COUNTRY_ROW');
}
return [{ json:payload }];
